// orval writes a beer emoji into every generated file header; strip it after codegen (no-emoji standard).
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const files = execFileSync('git', ['ls-files', '-z', 'lib/*/src/generated']).toString().split('\0').filter(Boolean);
for (const f of files) { const t = readFileSync(f, 'utf8'); const n = t.replace(/^( \* Generated by orval v[\d.]+) \u{1F37A}$/mu, '$1'); if (n !== t) writeFileSync(f, n); }
